const files = JSON.parse($input.first().json.stdout);

return files
  .filter(file => file.name.toLowerCase().endsWith('.md'))
  .map(file => ({
    json: {
      fileName: file.name,
      size: file.size
    }
  }));

const contents = $input.all();

const text = contents.map((item, index) => {
  const file = $('Replace Me').all(0, index)[0];

  return [
    `# TEMPLATE : ${file.json.fileName}`,
    '',
    item.json.data
  ].join('\n');
}).join('\n\n---\n\n');

return [
  {
    json: {
      text
    }
  }
];

const input = $input.first().json;

const source = input.doc?.text;
const templates = input.template;

if (typeof source !== 'string' || !source.trim()) {
  throw new Error('Invalid or empty source document');
}

if (!Array.isArray(templates)) {
  throw new Error('Invalid templates');
}

const boundaries = new Set([0, source.length]);

// Markdown line breaks
for (const match of source.matchAll(/\r?\n+/g)) {
  boundaries.add(match.index + match[0].length);
}

// Sentence boundaries
const sentencePattern = /[.!?][»”"']?[ \t]+(?=[A-ZÀ-ÖØ-Þ«“(])/g;

for (const match of source.matchAll(sentencePattern)) {
  boundaries.add(match.index + match[0].length);
}

// Numbered procedure steps
const stepPattern = /;[ \t]+(?=(?:puis[ \t]+)?\(\d+\))/gi;

for (const match of source.matchAll(stepPattern)) {
  boundaries.add(match.index + match[0].length);
}

const positions = [...boundaries].sort((a, b) => a - b);

const fragments = positions.slice(1).map((end, index) => {
  const start = positions[index];
  const text = source.slice(start, end);

  return {
    id: `F${String(index + 1).padStart(4, '0')}`,
    start,
    end,
    type: /^#{1,6}\s/.test(text) ? 'heading' : 'text',
    text
  };
});

// Exact reconstruction check
const reconstructed = fragments.map(f => f.text).join('');

if (reconstructed !== source) {
  throw new Error('Source reconstruction mismatch');
}

return [{
  json: {
    doc: input.doc,
    template: templates,
    fragments,
    balisage: {
      fragmentCount: fragments.length,
      sourceLength: source.length,
      exactReconstruction: true
    }
  }
}];

const source = $('Balisage source').first().json;
const response = $input.first().json.output?.[0];

if (response?.status !== 'completed') {
  throw new Error('LLM response is not completed');
}

let plan = response.content?.find(
  content => content.type === 'output_text'
)?.text;

if (typeof plan === 'string') {
  plan = JSON.parse(plan);
}

if (!Array.isArray(plan?.assignments)) {
  throw new Error('Invalid assignments array');
}

const fragments = source.fragments;
const templates = source.template;

const fragmentIds = new Set(
  fragments.map(fragment => fragment.id)
);

const allowedStatuses = new Set([
  'applicable',
  'historique',
  'contexte',
  'a_verifier'
]);

// Extract available fields from Markdown templates.
const templateFields = new Map();

for (const template of templates) {
  const fields = new Set();

  const pattern = /([^:[\]\r\n]+?)\s*:\s*\[[^\]\r\n]*\]/g;

  for (const match of template.text.matchAll(pattern)) {
    fields.add(match[1].trim());
  }

  templateFields.set(template.name, fields);
}

const errors = [];
const seen = new Set();
let destinationCount = 0;
let archiveCount = 0;
let templateCount = 0;

for (const assignment of plan.assignments) {
  const id = assignment.fragment_id;

  if (!fragmentIds.has(id)) {
    errors.push(`Unknown fragment: ${id}`);
  }

  if (seen.has(id)) {
    errors.push(`Duplicate fragment: ${id}`);
  }

  seen.add(id);

  if (!allowedStatuses.has(assignment.status)) {
    errors.push(`Invalid status: ${id}`);
  }

  if (
    !Array.isArray(assignment.destinations) ||
    assignment.destinations.length === 0
  ) {
    errors.push(`Missing destination: ${id}`);
    continue;
  }

  let hasArchive = false;
  const usedDestinations = new Set();

  for (const destination of assignment.destinations) {
    destinationCount++;

    if (destination.kind === 'archive') {
      archiveCount++;
      hasArchive = true;

      if (destination.template !== '' || destination.field !== '') {
        errors.push(`Invalid archive destination: ${id}`);
      }

    } else if (destination.kind === 'template') {
      templateCount++;

      const fields = templateFields.get(destination.template);

      if (!fields) {
        errors.push(`Unknown template: ${id}`);
      } else if (!fields.has(destination.field)) {
        errors.push(
          `Unknown field: ${id} / ${destination.field}`
        );
      }

    } else {
      errors.push(`Invalid destination kind: ${id}`);
    }

    const key = JSON.stringify([
      destination.kind,
      destination.template,
      destination.field
    ]);

    if (usedDestinations.has(key)) {
      errors.push(`Duplicate destination: ${id}`);
    }

    usedDestinations.add(key);
  }

  if (
    ['historique', 'a_verifier'].includes(assignment.status) &&
    !hasArchive
  ) {
    errors.push(`Archive required: ${id}`);
  }
}

// Check for missing fragments.
const missing = [...fragmentIds].filter(
  id => !seen.has(id)
);

for (const id of missing) {
  errors.push(`Missing fragment: ${id}`);
}

// Stop workflow if validation fails.
if (errors.length > 0) {
  throw new Error(
    `Cut plan validation failed (${errors.length} errors):\n` +
    errors.join('\n')
  );
}

return [{
  json: {
    ok: true,
    validation: {
      fragmentCount: fragments.length,
      assignmentCount: plan.assignments.length,
      destinationCount,
      templateCount,
      archiveCount,
      missingCount: 0,
      duplicateCount: 0,
      valid: true
    },
    doc: source.doc,
    template: templates,
    fragments,
    assignments: plan.assignments
  }
}];

const input = $input.first().json;
const init = $('init').first().json;

if (input.ok !== true) {
  throw new Error('Cut plan is not validated');
}

const fragments = input.fragments;
const templates = input.template;
const assignments = input.assignments;

const assignmentMap = new Map(
  assignments.map(item => [item.fragment_id, item])
);

// Prepare template field containers.
const templateFields = new Map();

for (const template of templates) {
  templateFields.set(template.name, new Map());
}

const archiveFragments = [];
const usedIds = new Set();
const templateFragmentIds = new Map(
  templates.map(template => [template.name, new Set()])
);

// Assign original fragments in source order.
for (const fragment of fragments) {
  const assignment = assignmentMap.get(fragment.id);

  if (!assignment) {
    throw new Error(`Missing assignment: ${fragment.id}`);
  }

  for (const destination of assignment.destinations) {
    if (destination.kind === 'archive') {
      archiveFragments.push(fragment);
      usedIds.add(fragment.id);
      continue;
    }

    const fields = templateFields.get(destination.template);

    if (!fields) {
      throw new Error(`Unknown template: ${destination.template}`);
    }

    if (!fields.has(destination.field)) {
      fields.set(destination.field, []);
    }

    fields.get(destination.field).push(fragment);
    templateFragmentIds.get(destination.template).add(fragment.id);
    usedIds.add(fragment.id);
  }
}

// Verify coverage before generation.
const missingIds = fragments
  .filter(fragment => !usedIds.has(fragment.id))
  .map(fragment => fragment.id);

if (missingIds.length > 0) {
  throw new Error(`Unassigned fragments: ${missingIds.join(', ')}`);
}

// Use source name to avoid overwriting other documents.
const originalName = $('params').first().json.body.name || 'document';

const sourceName = originalName
  .replace(/(?:\.(?:pdf|docx|doc|txt))?\.md$|\.(?:pdf|docx|doc|txt)$/i, '')
  .replace(/[^\p{L}\p{N}._-]/gu, '_');

const output = [];

// Generate one Markdown file per template.
for (const template of templates) {
  const fields = templateFields.get(template.name);

  // Fix template fields placed on the same line.
  const normalizedTemplate = template.text.replace(
    /(\[À RENSEIGNER\])\s+(?=Titre \/ sujet précis\s*:)/g,
    '$1\n\n'
  );

  const fieldPattern = /([^:[\]\r\n]+?)\s*:\s*\[[^\]\r\n]*\]/g;

  const content = normalizedTemplate.replace(
    fieldPattern,
    (match, label) => {
      const fieldName = label.trim();
      const selected = fields.get(fieldName) || [];

      const value = selected.length
        ? selected.map(fragment => fragment.text).join('\n\n')
        : 'Non documenté';

      return `${fieldName} : ${value}`;
    }
  );

  const templateName = template.name
    .replace(/^template_\d+_/, '')
    .replace(/\.pdf\.md$/i, '.md');

  output.push({
    json: {
      type: 'template',
      targetFolder: init.upload_path,
      name: `${sourceName}__${templateName}`,
      content,
      fragmentIds: [...templateFragmentIds.get(template.name)],
      fragmentCount: templateFragmentIds.get(template.name).size
    }
  });
}

// Generate archive from original fragments.
const archiveContent = [
  '# Archive documentaire',
  '',
  `Document source : ${originalName}`,
  '',
  ...archiveFragments.map(fragment => fragment.text)
].join('\n\n');

output.push({
  json: {
    type: 'archive',
    targetFolder: init.legacy_processed,
    name: `${sourceName}__archive.md`,
    content: archiveContent,
    fragmentIds: archiveFragments.map(fragment => fragment.id),
    fragmentCount: archiveFragments.length
  }
});

// Verify that each fragment exists in a generated file.
for (const fragment of fragments) {
  const found = output.some(item =>
    item.json.fragmentIds.includes(fragment.id) &&
    item.json.content.includes(fragment.text)
  );

  if (!found) {
    throw new Error(`Fragment missing from output: ${fragment.id}`);
  }
}

return output;
